      "EN2 — Examine, perceptively, involves evaluating the impact of media and processes on style and meaning in art works, using supporting contextual evidence.",
      "EN4 — Media refers to the materials and/or medium and/or technical means used to create art works (e.g. oil, watercolour, acrylic, ink, chalk, marble, bronze, wood, fibreglass, plastic, film, video, laser, digital images, multimedia technologies, performance).",
      "EN5 — Processes refer to a series of actions or steps taken to produce the art work.",
      "EN6 — Style refers to the characteristics of an art work that, when combined, distinguish the style of an artist, art movement, period or place (e.g. ways of using line, colour, tone, light, form, composition, space, scale, shape, mass, texture, ornament, media).",
      "EN7 — Meaning refers to the ideas, messages and/or themes conveyed through the features of art works (technical devices, formal elements, subject matter, iconographic motifs, symbols, emblems, action or performance elements)."
