       "Notes or annotated images are acceptable; bullet-pointed lists of single words are not sufficient for Achieved.",
       "Achieved typically: explanations linking specified aspects of media and processes with the styles and meanings of selected works. Merit: detailed explanations of those connections. Excellence: evaluative discussion of the various impacts of different media and processes on styles and meanings, with relevant contextual evidence."
