      "Strong evidence made explicit connections, e.g. how Boltanski's heartbeat recordings in Personnes relate to existentialist meanings and viewer interpretation.",
      "Works must represent at least two different media or processes: three oil paintings, even by different artists, is insufficient; an oil painting combined with a sculpture is appropriate.",
      "Responses should analyse impact rather than give lengthy descriptive accounts of how works were made."
