     "criteria": {
      "achieved": "Construct an argument based on interpretation of research in art history.",
      "merit": "Construct a reasoned argument based on interpretation of research in art history.",
      "excellence": "Construct a perceptive argument based on interpretation of research in art history."
     },
     "notes": [
      "EN2 — Construct an argument involves selecting and interpreting researched information to develop an argument.",
      "EN2 — Construct a reasoned argument involves selecting and interpreting researched information to develop a justified argument.",
      "EN2 — Construct a perceptive argument involves synthesising researched information to develop an insightful and/or evaluative argument.",
      "EN3 — An argument discusses points of view from art history sources and reaches conclusions. It may be based on: a topic, a concept, a question, an issue, a detailed study of a particular aspect of art."
     ],
     "clarifications": {
      "date": "Updated August 2015",
      "points": [
       "An argument discusses points of view and reaches one or more conclusions; points of view may cover a range of opinions or interpretations and need not be opposed or debatable.",
       "The topic must relate to art history and give enough scope to explain and evaluate points of view; teacher or student may choose it.",
       "Any format (debate, speech, digital commentary, essay, scripted PowerPoint) is allowed, but written or recorded evidence is required for moderation. Notes, diagrams or annotated images alone are unlikely to be sufficient; formal sentence structure and linked paragraphs are not essential.",
       "Research materials must include art history sources and allow students to select and process information; teachers may supply them if broad enough.",
       "Research skills such as annotating sources and bibliographies are NOT assessed.",
       "Achieved typically: discusses points of view reaching conclusions using research. Merit: explains researched points and ideas with supported, justified conclusions. Excellence: weaves pertinent information into an evaluation reaching convincing conclusions."
      ]
     },
     "nmr": [
      "Successful responses (2025) presented a clear argument, framed either as a debate (agreeing/disagreeing with a proposition) or as persuasive writing; exploring more than one point of view gave more nuanced, well-supported conclusions.",
      "Arguments based on debatable, thought-provoking questions worked best.",
      "Topics were often too broad (why an artist is famous; how works show typical movement characteristics), which limits argument.",
      "Use question wording that invites debate, e.g. 'To what extent…?' or 'How significant was…?'"
     ],
