      "EN4 — Theory refers to a set of principles and ideas which can be examined in relation to art, e.g. Platonism, Humanism, Neoplatonism, Marxism, Theosophy, Utopianism, Neoplasticism, Psychoanalytical theory (Freudian, Jungian), Existentialism, Feminism, Post-Colonialism.",
