     "title": "Analyse texts about art",
     "criteria": {
      "achieved": "Analyse texts about art.",
      "merit": "Analyse, in depth, texts about art.",
      "excellence": "Analyse, perceptively, texts about art."
     },
     "notes": [
      "EN2 — Analyse involves explaining ideas and views expressed by the author(s) of the texts and identifying interpretations about art, using supporting evidence from the texts.",
      "EN2 — Analyse, in depth, involves linking the ideas and views expressed by the author(s) of the texts and interpretations about art, using supporting evidence from the texts and/or other sources.",
      "EN2 — Analyse, perceptively, involves evaluating the significance of the ideas and views expressed by the author(s) of the texts and interpretations about art and drawing conclusions.",
      "EN3 — Texts about art may include: oral, written, or visually recorded texts."
     ],
     "clarifications": {
      "date": "Updated August 2015",
      "points": [
       "A text is any set of words constructed to inform or express ideas — written (books, articles, reports) or multimedia (films, online clips).",
       "Texts must be about art, suit the students' level, and give scope to explain and evaluate the authors' ideas and views. Art works must NOT be used as the texts for this standard.",
       "Supporting evidence comes from the texts and/or other sources (aspects of works, context, other texts); random quotations or references not connected to the explanations do not count.",
       "Class discussion is allowed but the assessed response must be the student's own, written or recorded; bullet-pointed lists of single words are insufficient.",
       "Achieved typically: explanations of authors' ideas and views and identification of interpretations about art, with evidence from the texts. Merit: explanations of links between authors' ideas/views and interpretations, with evidence from texts and other sources. Excellence: evaluative discussion reaching conclusions about the significance of the authors' ideas, views and interpretations."
      ]
     },
     "nmr": [
      "Successful responses (2025) identified the author's key ideas and explained how they were reflected in the chosen art works; stronger responses broke viewpoints into specific components and evaluated their significance.",
      "Most effective texts are those where authors clearly state views on specific aspects of art, leaving room to agree, disagree or offer alternatives.",
      "Use consistent, explicit evidence from the texts, such as direct quotations, and analyse it in detail.",
      "Choose texts with clear viewpoints rather than general descriptive information about works or movements."
     ],
