   "discipline": "Level 3 Biology internals are judged on biological understanding at curriculum level 8: ideas described (Achieved), explained how or why (Merit), and linked through analysis, evaluation or justification (Excellence), with investigations and responses driven by the student. Detail must be accurate and specific to the chosen system, organism or issue rather than general textbook coverage. Length, protocol detail and the volume of facts are never the criterion; the quality of explanation and linking is.",
