      "EN2 — Demonstrate comprehensive understanding (Excellence) involves linking biological ideas about maintaining a stable internal environment in an animal. This includes at least one of: a discussion of the adaptive significance of the control system; a discussion of the biochemical and/or biophysical processes underpinning the mechanism (such as equilibrium reactions, changes in membrane permeability, metabolic pathways); an analysis of a specific example of how external and/or internal environmental influences result in a breakdown of the control system.",
