     "verified": "2026-10-25",
     "title": "Analyse a human resource issue affecting businesses",
     "criteria": {
      "achieved": "Analyse a human resource issue affecting businesses.",
      "merit": "Analyse, in depth, a human resource issue affecting businesses.",
      "excellence": "Comprehensively analyse a human resource issue affecting businesses."
     },
     "notes": [
      "EN2 — Analyse typically involves collecting evidence relevant to a human resource issue, explaining a human resource issue and a possible solution through: stating business knowledge relevant to a solution; stating a Māori business concept(s) where relevant to a solution.",
      "EN2 — Analyse, in depth, typically involves collecting evidence relevant to a human resource issue, fully explaining a human resource issue and a range of possible solutions through: including business knowledge relevant to a solution; including a Māori business concept(s) where relevant.",
      "EN2 — Comprehensively analyse typically involves collecting evidence relevant to a human resource issue from a range of sources, evaluating a human resource issue and recommending the best possible solution through: integrating business knowledge relevant to a solution; integrating a Māori business concept(s) where relevant.",
      "EN3 — Human resource issue refers to any complex problem relating to the human resources that affects businesses.",
      "EN4 — A range of possible solutions refers to two or more solutions.",
      "EN5 — A range of sources refers to two or more sources.",
      "EN6 — Best possible solution refers to best in the student’s reasoned opinion."
     ],
     "clarifications": {
      "date": "December 2018",
      "points": [
       "The issue is a complex problem significant enough to affect at least two New Zealand businesses. International research or overseas businesses may be referenced, but the focus is the issue’s effect on New Zealand businesses operating in a global context.",
       "Evidence comes from or about NZ businesses that have faced the issue — primary data such as interviews with owners or managers, or sources such as Statistics NZ, employer associations or the Employment Law Database. The teacher advises whether an issue can support comprehensive analysis.",
       "Example issues: employees’ personal social media use and productivity; pressure to pay a living wage; shortage of skilled construction workers; recruitment and retention of secondary teachers.",
       "Students explain the issue, evaluate how it arose and assess its potential consequences for businesses. Stakeholder effects add context but the main focus is the business community.",
       "Achieved: one feasible solution the business community could implement. Merit and Excellence: at least two possible solutions. Excellence: the best solution recommended.",
       "When explaining why solutions suit the issue, students show understanding of the relevant parts of the human resource cycle: workforce planning, change management, employment relations, employment law, training, motivation, appraisal."
      ]
     },
     "nmr": [
      "Two specific New Zealand businesses affected by the issue are required, with evidence from those businesses or reliable NZ research or statistics. Some 2025 submissions lacked evidence from or about two NZ businesses.",
      "Industry trends may support the analysis but cannot meet the standard alone; the focus must stay on how the issue affects specific businesses.",
      "Choose HR issues, not broader social issues: social trends shape consumer behaviour, HR trends change how businesses manage people. A social issue (e.g. quad bike accidents) can become an HR issue for farms through lost work, injury costs, training and retention.",
      "Solutions must be realistic, lawful and within the businesses’ control — a government pay decision for public health is not a business-level solution (it could be for private health businesses).",
      "Accurate knowledge of the HR cycle (training, appraisal, legislation, employment relations) is needed."
     ],
