     "notes": [
      "EN2 — Demonstrate understanding (Achieved) involves: using primary source evidence; analysing an aspect(s) of significant ideology(ies) in the classical world; relating the ideology(ies) to a wider context.",
      "EN2 — Demonstrate in-depth understanding (Merit) involves undertaking an informed analysis of significant ideology(ies) in the classical world. Features of an informed analysis include using primary source evidence of specific relevance to the context and analysing a range of aspects and/or factors.",
      "EN3 — Demonstrate perceptive understanding (Excellence) involves showing insight into a range of aspects and/or factors of significant ideology(ies). Features MAY include reasons for similarities and differences, establishing themes and patterns, identifying cultural expectations and codes of behaviour, and showing discernment regarding limitations of sources of evidence.",
      "EN4 — Ideology(ies) means religious, philosophical or political belief systems, e.g. religions, Stoicism, Epicureanism, Socratic moral philosophy, Alexander’s Oriental policy."
     ],
