      "points": [
       "Achieved: analyse one aspect of a significant ideology, supported by primary source evidence, and connect the ideology to a wider context. The wider context may be in the classical world or a later culture (e.g. 4th-century CE changes in Christian ideology affecting church doctrine).",
       "Merit: in-depth understanding of SEVERAL aspects or factors; the context chosen must have enough aspects to make this achievable. Teachers use professional judgement on whether the detail is sufficient.",
       "Excellence: the analysis must show insight, which varies by context. The EN descriptors are guidance for teachers and students, not a separate set of criteria. Quality of response matters more than quantity.",
       "Authenticity must be verified; a bibliography is one method, but its absence alone cannot prevent achievement at any level."
      ]
