      "EN2 — Demonstrate perceptive understanding (Excellence) involves providing an analysis that shows insight into the influences of aspects of the classical world on other cultures at three different points in time. Features may include reasons for similarities and differences, themes and patterns, cultural expectations and codes of behaviour, and discernment about limitations of sources.",
      "EN2 — Cultures at three different points of time refers to one of: ancient Greece, ancient Rome, and one post-Classical culture; OR ancient Greece or ancient Rome, and two post-Classical cultures.",
