       "Students must EXPLICITLY show how the classical culture influenced later cultures, directly or indirectly. Simple comparison or contrast is insufficient.",
       "Contexts need sufficient, accessible primary source evidence and clear influence over time.",
       "At least three points in time, including at least one classical: one classical (Greek or Roman) plus two later, or Greek, Roman and one later.",
       "Students need sufficient support (resources or guidance on ideas and values) to engage with the post-classical context.",
       "Achieved: analyse aspects of the classical world and other cultures with primary evidence, and discuss how the classical world influenced them.",
       "Merit: in-depth understanding of a range of aspects or factors; the context must have enough aspects; students must LINK the three points in time; teachers use professional judgement on sufficiency of detail.",
       "Merit and Excellence: students must develop hypotheses about the lasting influence; a single hypothesis carried through the analysis may be appropriate, and the influence must still be sufficiently analysed.",
