   "slug": "digital-technologies",
   "discipline": "Level 3 Digital Technologies 3.1 is judged on the quality of a critical inquiry that LEADS to a proposal: a broad focus refined through research and analysis into a detailed, buildable proposal with justified risks and mitigations, then (Merit) perspectives, future opportunities, managed milestones and the proposal's strengths and weaknesses, then (Excellence) critique of sources, findings and the proposal's issues. Building the outcome, technical polish and the volume of research gathered are never the criterion.",
   "parallelHint": "a different community issue or end-user group leading to a different kind of digital outcome (e.g. a learning resource vs a monitoring device vs a database), so students cannot copy the research, risks or proposal",
   "privacyNote": "",
