     "notes": [
      "EN2 — Conduct a critical inquiry (Achieved) involves: deciding on an inquiry focus and developing specific inquiry question(s); undertaking research to gather background information and ideas; analysing gathered information; establishing a refined inquiry focus; proposing a digital technologies outcome to the inquiry; explaining relevant risks and ways to mitigate these risks; reporting on the findings of the research in relation to the inquiry question(s) and proposed digital technologies outcome.",
      "EN2 — Conduct an in-depth critical inquiry (Merit) involves: comparing and contrasting different perspectives that relate to the inquiry focus; discussing possible future opportunities relating to the inquiry focus and explaining the possible impacts of these opportunities; effectively managing milestones and inquiry progression; evaluating the strengths and weaknesses of the proposed digital technologies outcome.",
      "EN2 — Conduct a comprehensive critical inquiry (Excellence) involves evaluating the findings and implications including: critiquing any sources used and evaluating their potential for bias and inaccuracies; considering possible issues relating to the proposed outcome and suggesting areas for improvement, extension, and/or follow-up; critiquing the accuracy, relevance, reliability, and/or significance of the findings.",
      "EN3 — Examples of risks include: time; financial; estimations and scheduling; incorrect functionality; scope creep; factors outside of one's control."
     ],
     "clarifications": {
      "date": "December 2021 (updated to address issues arising from moderation)",
      "points": [
       "The task must be broad enough that the inquiry lets students choose from a range of possible digital technologies outcomes. The context may be provided.",
       "Students must show how they decided on the focus and developed inquiry questions linked to digital technologies.",
       "Background research must be relevant and show how digital technologies could address the inquiry question(s); students need not present everything they gathered.",
       "Analysis gives a concise summary and examines what was found; its results guide the refined inquiry focus.",
       "The proposal must be detailed enough for a student to develop it into an outcome: purpose, end users, scope, requirements and specifications, and resources needed.",
       "Relevant risks for the proposed outcome are described in detail and justified, with possible ways to address them and reduce their impact.",
       "Findings are reported in detail, explaining how they affect the proposed outcome.",
       "Merit: compare and contrast the relevant perspectives affecting the inquiry focus; discuss future opportunities by exploring the findings and considering their impact.",
       "Merit: evidence of reflection on and documentation of process and progress — effective goals, planned and organised progression, milestones met, and any variations from the plan explained.",
       "Merit: identify the proposed outcome's strengths and weaknesses and consider their impact, including whether it will address the issues in the inquiry focus and question(s).",
       "Excellence: sources examined in detail for relevance and accuracy, with biases discussed; possible issues with the proposed outcome considered, improvements put forward and extensions explained; findings examined in detail for accuracy, relevance or reliability."
      ]
     },
     "nmr": [
      "At Level 3 the inquiry focus must be refined BEFORE an outcome is proposed — students start with a broad focus and open questions, and the outcome should emerge from the inquiry rather than being decided in advance (a key difference from Level 2).",
      "Strong evidence began with students documenting a range of issues of concern to them, from 'genuine care and curiosity about the world around you'.",
      "Achieved: more than one relevant risk is expected, each with a mitigation (e.g. the risk of missing a deadline mitigated with planning tools and milestones).",
      "Achieved: the proposal needs enough detail to support further development — purpose, end users, physical and functional requirements, technical specifications, and resources such as hardware and software.",
      "Merit: perspectives can include end users, people of different ages, educational or cultural backgrounds, and people with positive or negative attitudes to the issue. Future opportunities should draw on the research (e.g. expanding the outcome or adapting it for other environments).",
      "Merit: strengths and weaknesses must relate to the proposed OUTCOME, not the inquiry process, with more than one of each expected. A timeline alone does not show milestone management; students must show how it was followed or adjusted.",
      "Excellence: ideally all sources are critiqued for bias and inaccuracy, and findings critiqued for accuracy, relevance, reliability and significance."
     ],
