   "discipline": "Level 3 Drama 3.5 is judged on APPLICATION: the student applies a theorist's or practitioner's knowledge, ideas or processes to a text or role to communicate the intention of that person's work, then justifies that application against the practitioner's intention (Merit) and does so with insight (Excellence). Describing the practitioner's life or the features of a theatre form is never enough, and performance polish is never the criterion.",
