     "code": "91516",
     "ref": "3.5",
     "credits": 4,
     "version": "Version 2 (published 17 November 2016)",
     "verified": "2026-10-25",
     "title": "Demonstrate understanding of the work of a drama or theatre theorist or practitioner",
     "criteria": {
      "achieved": "Demonstrate understanding of the work of a drama or theatre theorist or practitioner.",
      "merit": "Demonstrate informed understanding of the work of a drama or theatre theorist or practitioner.",
      "excellence": "Demonstrate perceptive understanding of the work of a drama or theatre theorist or practitioner."
     },
     "notes": [
      "EN2 — Demonstrate understanding (Achieved) involves applying the knowledge, and ideas or processes of a practitioner or theorist to communicate the intention of their work.",
      "EN2 — Demonstrate informed understanding (Merit) involves justifying the application in relation to the intention of the work of a practitioner or theorist.",
      "EN2 — Demonstrate perceptive understanding (Excellence) involves justifying, with insight, the application in relation to the intention of the work of a practitioner or theorist.",
      "EN3 — A drama or theatre theorist is a person whose writing and/or practice has been innovative and influential in shaping world theatre.",
      "EN4 — A practitioner is a person who has (or has had) a significant influence on the development of theatre or drama practice.",
      "EN5 — Applying refers to implementation in a presentation or practical demonstration of knowledge and understanding gained through research and practical exploration."
     ],
     "clarifications": {
      "date": "May 2022 (updated to address issues arising from moderation)",
      "points": [
       "Achieved: students must apply the practitioner's or theorist's knowledge, ideas or processes to communicate the theorist's intent, to a text or role studied in class — e.g. running an in-role workshop or rehearsal in the style of Stanislavski, using his theories to coach actors and build characters.",
       "Assessment must address the application of the ideas. Evidence can be a physical enactment of text, or an essay or seminar (which may include an in-role presentation or slideshow).",
       "Describing a theatre form's key features is not enough; identifying those features in a play to convey themes belongs to the external standard 91514.",
       "Biographical details count only where they relate to applying the theory; factual knowledge about the person is not assessment evidence.",
       "Merit: the justification must explain why the theory applied is appropriate in that context. Guiding questions: why and where would the theorist, as director, designer or actor, use this aspect of the theory? What meaning could the application communicate to the audience?",
       "Excellence: a practical demonstration of the application supports deeper insight (e.g. justifying Stanislavski's methods to build a 'truthful' and 'realistic' character and explaining how this brings out the play's underlying themes for the audience). Insight is evidenced by the criticality of the accompanying justified explanation."
      ]
     },
