     "title": "Demonstrate understanding of government interventions where the market fails to deliver efficient or equitable outcomes",
     "criteria": {
      "achieved": "Demonstrate understanding of government interventions where the market fails to deliver efficient or equitable outcomes.",
      "merit": "Demonstrate in-depth understanding of government interventions where the market fails to deliver efficient or equitable outcomes.",
      "excellence": "Demonstrate comprehensive understanding of government interventions where the market fails to deliver efficient or equitable outcomes."
     },
     "notes": [
      "EN2 — Demonstrate understanding involves: providing an explanation of why the market may not be delivering efficient or equitable outcomes, government interventions, and the implications of the government interventions for equity and efficiency; using an economic model(s) to support an explanation(s).",
      "EN2 — Demonstrate in-depth understanding involves: providing a detailed explanation of why the market may not be delivering efficient or equitable outcomes, government interventions, and the implications of the government interventions for equity and efficiency; using an economic model(s) to support a detailed explanation(s).",
      "EN2 — Demonstrate comprehensive understanding involves: using a detailed explanation to make a justified recommendation on which government intervention is better in terms of efficiency and equity; integrating an economic model(s) into the justified recommendation.",
      "EN3 — Market situations include consumption externalities, production externalities, public goods, imperfect information, inequitable income and/or wealth distribution, and under-provision of merit goods or services.",
      "EN4 — Interventions by central or local government include subsidies, taxes, regulations, property rights, government provision, progressive taxes, welfare benefits, collective provision, minimum wage, government grants and targeted services, matched to the market failure."
     ],
     "clarifications": {
      "date": "December 2018",
      "points": [
       "Students show understanding of at least TWO interventions addressing ONE market failure (e.g. a consumption or production externality, a public good, imperfect information) or one inequitable market situation (inequitable income or wealth distribution, under-provision of a merit good or service).",
       "Version 3 requires BOTH equity and efficiency of the interventions to be considered, explained as implications for society, using an economic model.",
       "The model must illustrate a whole market, not individual consumption: SMC/SMB (adapted supply and demand) for externalities; the Lorenz curve for inequitable income or wealth distribution.",
       "Identify the good type: normal goods (excludable, rivalrous) use S/D and SMC/SMB; public goods (non-excludable, non-rivalrous, e.g. street lighting) use the public goods model.",
       "Public healthcare is rivalrous (waiting lists) and costly to access, so it is an under-provided merit good with inequitable access (e.g. for low-income and rural communities); the public goods model can show collective provision versus user-pays for public healthcare or education. Under-provision also covers housing, walking tracks and public infrastructure."
      ]
     },
