   "discipline": "Level 3 English internals are judged at curriculum level 8. The reading and viewing standards ask for a CRITICAL response: evaluative interpretations and judgements (Achieved), discerning and informed (Merit), sophisticated and insightful and/or original (Excellence), always grounded in specific detail from the texts. The writing standard is judged on understanding of purpose and audience shown through the selection and integration of ideas, language and structure, culminating in a ‘striking whole’. Summary, background information and length never earn credit in themselves.",
