     "conditions": [
      "Provide multiple opportunities to draft and craft several pieces; each includes planning, drafting, revising, proofreading and editing, spread over an extended period. Drafts may be parked and returned to.",
      "‘Hands on’ skill-building work is not suitable for summative assessment; ‘hands off’ independent work can be assessed.",
      "Teachers may advise whether a final draft needs more work on ideas, language, structure or accuracy, and may demonstrate techniques with sample texts, but must not correct errors, rewrite sentences, make detailed annotations, or give verbal feedback on individual errors.",
      "Assessors closely supervise the writing process, check for unacknowledged copying, limit feedback to general suggestions linked to the criteria, and use observations, conversations and checkpoints to confirm authenticity.",
      "Students must not use any generative AI or other tools to automatically generate content at any stage.",
      "No minimum or maximum word count; each piece is recommended to be at least 650 words. Significantly shorter pieces may mean more than two are submitted.",
      "TKI resources 3.4A/3.4B: at least two pieces; the final grade is a holistic judgement of the selection; drafts stored or printed to document the process; time given to receive feedback, edit, revise and polish."
     ],
