     "code": "91478",
     "ref": "3.7",
     "credits": 4,
     "version": "Version 1 (published 4 December 2012)",
     "verified": "2026-10-25",
     "title": "Respond critically to significant connections across texts, supported by evidence",
     "criteria": {
      "achieved": "Respond critically to significant connections across texts, supported by evidence.",
      "merit": "Respond critically and convincingly to significant connections across texts, supported by evidence.",
      "excellence": "Respond critically and perceptively to significant connections across texts, supported by evidence."
     },
     "notes": [
      "EN1 — Texts chosen should be at Curriculum Level 8 and/or have characteristics that allow students to meet the expected level of critical response.",
      "EN2 — Respond critically involves making evaluative interpretations and judgements. Respond critically and convincingly involves making discerning and informed interpretations and judgements. Respond critically and perceptively involves making sophisticated and insightful and/or original interpretations and judgements.",
      "EN3 — Significant refers to how aspects and interpretations of the text create meaning.",
      "EN4 — Connections relate to how all texts are linked in relation to a selection from: purposes and audiences; ideas, knowledge, and experience; language features; and structures.",
      "EN5 — Supported by evidence refers to the use of specific and relevant details to support an argument. This may include quotations and/or references to the studied texts and/or other sources.",
      "EN6 — At least four texts must be included, at least one of which must be student-selected. Texts may be written, visual and/or oral, short and/or extended, or any combination.",
      "EN7 — Critical responses may be presented in oral, written and/or visual forms, or a combination."
     ],
     "clarifications": {
      "date": "Updated December 2017 (revised in its entirety from moderation)",
      "points": [
       "Students make connections across four texts (written, visual or oral), at least one self-selected, and give a critical response supported by specific details or examples from each text.",
       "Connections are commonalities such as theme, setting, author, narrative perspective or genre. One broad ‘umbrella’ commonality can be used if differentiated so evaluations are made across all texts; or more than one commonality from the start, provided the student moves beyond identification to the required critical response across all texts.",
       "Connections must be sophisticated enough to produce discriminating and insightful understanding of ideas across texts.",
       "Texts must allow exploration of ideas at level 8; a text below that level may be included to help make evaluative judgements or support an argument.",
       "Students first identify the connections and show how aspects and interpretations create meaning, then make evaluations and judgements about the connections supported by those interpretations.",
       "A critical response includes evaluative interpretations of wider society, issues and contexts and an understanding of the author’s purpose and audience, and must be well grounded in the texts. Discussion of current issues or events must be supported by identifying their importance and giving examples from within the texts."
      ]
     },
