     "title": "Develop an informed understanding of literature and/or language using critical texts",
     "criteria": {
      "achieved": "Develop an informed understanding of literature and/or language using critical texts.",
      "merit": "Develop an informed and convincing understanding of literature and/or language using critical texts.",
      "excellence": "Develop an informed and perceptive understanding of literature and/or language using critical texts."
     },
     "notes": [
      "EN1 — Texts should be at Curriculum Level 8 or have characteristics that allow students to reach the expected level of informed understanding.",
      "EN2 — Develop an informed understanding involves developing a coherent reading, critique, and interpretation which includes judgements, commentary, and details and/or examples.",
      "EN2 — Develop an informed and convincing understanding involves demonstrating understandings that are discerning. Develop an informed and perceptive understanding involves demonstrating understandings that are sophisticated and insightful and/or original.",
      "EN3 — Literature and/or language includes written, oral and visual texts.",
      "EN4 — Critical texts may include linguistic or literary theory, criticism, and/or analysis. They may be written, oral, and/or visual texts. Texts are student selected.",
      "EN5 — Using critical texts is a process that involves: developing a hypothesis or theory to frame an investigation; selecting critical texts; selecting information and evaluating its reliability and usefulness in relation to the investigation; synthesising information from primary source(s) and critical texts (e.g. using readings from different critics to interpret Othello’s motivation; using feminist theory to interpret advertising language).",
      "EN6 — Understandings may be presented orally, in writing, visually, or in a combination."
     ],
     "clarifications": {
      "date": "Updated December 2023 (from moderation)",
      "points": [
       "Level 8 requires a coherent reading, critique and interpretation: students use critical texts to build an informed understanding of the primary text. Starting with a range of secondary texts may help students find at least two suitable ones.",
       "Teachers may help students choose critical texts through suggested lists, prompts, questions or discussion of suitability.",
       "The area of inquiry should reflect level 8 objectives, have breadth and depth to support conclusions, and come from a literature text or language topic the student already understands.",
       "Students must engage with at least TWO critical texts of appropriate depth for level 8, written by experts. Summary resources (e.g. SparkNotes, the Purdue OWL guide to literary theory) are useful teaching tools but do not count as critical texts, because they do not support the synthesis EN5 requires.",
       "Students form a hypothesis, select and process relevant critical texts, then combine expert information with the primary source(s) to reach evaluative conclusions and judgements. Evidence is required, including an evaluation of the reliability and usefulness of clearly acknowledged sources.",
       "Students generally need help finding and using critical texts, understanding plagiarism and turning information into their own ideas; journal databases such as EPIC or Google Scholar are useful."
      ]
     },
