      "EN3 — Close reading involves a detailed exploration and consideration of significant aspects of texts.",
      "EN4 — Texts for close reading have not been studied before and may be complete works or extracts; responses may refer to one or more texts, including combinations across film, television, drama, multi-media, graphic novel, radio, digital, online and oral performance.",
      "EN5 — Aspects may include audiences and purposes; ideas (themes, attitudes, beliefs, feelings, meanings); language features (cinematography, mise-en-scène, editing, sound, performance, rhetorical devices); structures (narrative sequence, beginnings and endings).",
