     "code": "91430",
     "ref": "3.5",
     "credits": 5,
     "version": "Version 3 (published December 2024)",
     "verified": "2026-10-25",
     "title": "Conduct geographic research with consultation",
     "criteria": {
      "achieved": "Conduct geographic research with consultation.",
      "merit": "Conduct in-depth geographic research with consultation.",
      "excellence": "Conduct comprehensive geographic research with consultation."
     },
     "notes": [
      "EN2 — Achieved involves: identifying the aim of the research; planning the research; collecting and recording data relevant to the aim of the research; presenting, using the correct geographic conventions and terminology, spatial, statistical, and/or visual data; analysing findings incorporating the relevance of geographic concepts; providing a conclusion(s) that relates to the aim of the research; providing an evaluation of the research process, and how this affects the validity of the research findings.",
      "EN2 — In depth (Merit) involves: effectively presenting spatial, statistical, and visual data, using the correct geographic conventions and terminology; analysing findings, in detail, incorporating the relevance of geographic concepts; providing a conclusion(s), in detail, that relates to the aim of the research; evaluating the research process and how this affects the validity of the research findings and/or conclusions.",
      "EN2 — Comprehensive (Excellence) involves: critically analysing findings, incorporating the relevance of geographic concepts; critically evaluating the research process by building on the detailed evaluation through a discussion of alternative research methods and their implications.",
      "EN3 — Geographic research is an investigative process about a particular area or environment and always has a spatial component.",
      "EN4 — With consultation means students will conduct their own geographic research, with the option to initiate discussion of this research with their teacher (e.g. planning, the aim and relevant concepts, presenting findings, analysing findings, evaluating the process).",
      "EN5 — Data must include primary data collected by the student, individually or in a group (observation, measurement, sketching, photography, surveys, questionnaires, interviews). Secondary data may be included, but the main focus must be primary data.",
      "EN6 — Students must individually create visual representations from processed data (e.g. annotated maps, graphs, annotated photographs, diagrams) using correct geographic conventions and terminology."
     ],
     "clarifications": {
      "date": "June 2025 (updated for Version 3)",
      "points": [
       "Version 3: presented data must use correct conventions and terminology; ‘maps’ broadened to spatial data; geographic concepts related to the research must be built into the analysis of findings; more support on what counts as consultation.",
       "The standard focuses on the research process, mainly primary data collected in the field. Students manage the process, but teachers may set a framework for topic choice (location or theme) so the topic has a spatial component and enough field data can be collected.",
       "Students must show evidence of each component in the final report, including planning and data collection.",
       "Secondary data supports critical analysis and evaluation. Spatial evidence might include maps, précis sketches, cross-sections and similar.",
       "Analysing findings uses the presented data to explore patterns, trends and relationships, going beyond simple explanation, with concepts directly linked to the research.",
       "Critical analysis (Excellence) examines findings more closely: factors that may have influenced them, irregularities, unexpected relationships.",
       "Evaluation focuses on the research process and how its strengths and weaknesses affect validity of findings and/or conclusions. Critical evaluation extends this by discussing alternative methods and their implications, to address weaknesses or build on strengths."
      ]
     },
