     "ref": "3.6",
     "credits": 3,
     "version": "Version 2 (published 17 November 2016)",
     "verified": "2026-10-25",
     "title": "Analyse aspects of a contemporary geographic issue",
     "criteria": {
      "achieved": "Analyse aspects of a contemporary geographic issue.",
      "merit": "Analyse, in depth, aspects of a contemporary geographic issue.",
      "excellence": "Analyse comprehensively aspects of a contemporary geographic issue."
     },
     "notes": [
      "EN2 — Analyse (Achieved) involves: explaining the nature of the contemporary geographic issue; explaining how people’s values and perceptions of the issue have led to their responses; proposing a suitable course of action to address the issue and justifying the proposed solution.",
      "EN2 — In depth (Merit) involves: explaining in detail how people’s values and perceptions of the issue have led to their responses; proposing a suitable course of action and providing a detailed justification of the proposed solution. The justification demonstrates why the chosen course of action is better than the alternatives.",
      "EN2 — Comprehensively (Excellence) involves: fully explaining how people’s values and perceptions of the issue have led to their responses; proposing a suitable course of action and providing a full justification of the solution showing insight. The full justification is an in-depth response that uses clarity of argument and holistic understanding to demonstrate why one course of action is better than the alternatives.",
      "EN3 — A justification must consider at least one alternative solution to the proposed course of action.",
      "EN4–6 — Aspects are the nature of the issue and the values and perceptions linked to it. A contemporary issue is affecting people or places now and is unresolved. A geographic issue is a topic, concern, problem, debate or controversy connected to a natural or cultural environment that has a spatial dimension."
     ],
     "clarifications": {
      "date": "September 2015 (updated to address issues from moderation)",
      "points": [
       "The issue must be currently unresolved and have a spatial dimension. For global topics, set the issue’s parameters and define its spatial dimension (e.g. sea-level rise for selected Pacific Islands rather than global warming).",
       "Two or three people or groups provide sufficient evidence. The focus is the response people make; students do best when the person or group has taken an active rather than passive response, and must clearly explain how the response results from their values and perceptions.",
       "Students must consider alternatives. The justification should examine short- and long-term implications of the proposal and the alternatives, and may consider environmental, economic, social and political impacts; a compromise or multifaceted long-term approach may be proposed.",
       "A full justification shows comprehensive understanding of the issue and alternatives, with clear argument and detailed evidence.",
       "Students need to use geographic terminology and show application and integration of concepts throughout."
      ]
     },
