   "discipline": "Level 3 Health is judged on a critical perspective applied at every grade: questioning assumptions, asking who benefits and who is disadvantaged, and connecting an issue, practice or debate to the underlying concepts (hauora, socio-ecological perspective, health promotion, attitudes and values), supported by specific, current, credible New Zealand-relevant evidence. Grades rise from explained, to in depth with detailed evidence, to perceptive (focused on the most crucial aspects, coherent, consistently evidenced). Length, number of sources or copied information is never the criterion.",
   "parallelHint": "a different New Zealand health issue, health circumstance or ethical issue, e.g. vaping among 15-24 year olds instead of alcohol misuse, chronic back pain instead of depression, organ donation instead of euthanasia",
   "privacyNote": "Student work in Health often includes personal disclosures (their own or whānau experiences of illness, mental health, drug use, sexuality, family violence, abortion or end-of-life decisions). If anything in the work suggests a student may be unsafe or at risk (self-harm, abuse, violence, coercion, serious distress), the AI must say so to the teacher in a separate line at the very top of its response, before any grading, and must not grade around it or quote it back. Feedback should never ask a student to disclose more personal detail than the task requires.",
