     "title": "Analyse a contemporary ethical issue in relation to well-being",
     "criteria": {
      "achieved": "Analyse a contemporary ethical issue in relation to well-being.",
      "merit": "Analyse, in depth, a contemporary ethical issue in relation to well-being.",
      "excellence": "Analyse, perceptively, a contemporary ethical issue in relation to well-being."
     },
     "notes": [
      "EN2 — Analyse (Achieved) involves providing a critical account of the ethical issue through: explaining the differing and opposing perspectives on the issue, and the reasons for these different perspectives; explaining the implications of current related health practices for the well-being of those directly affected by the issue, others associated with those people, and the well-being of people and society.",
      "EN2 — Analyse, in depth (Merit) involves providing a balanced view of the differing and opposing perspectives with some reference to underlying health concepts (hauora, socioecological perspective, health promotion, attitudes and values).",
      "EN2 — Analyse, perceptively (Excellence) involves: examining the perspectives on the issue with insight into the reasons for these differing perspectives and their ethical foundations; linking the examination to underlying health concepts.",
      "EN3 — A contemporary ethical issue is a health-related issue of current public concern where there are differing perspectives held by individuals and groups. The nature of these perspectives presents a dilemma for people and society (irrespective of any legal position that may determine current practice). Issues may be derived from: euthanasia, immunisation, organ donation, access to fertility treatment, reproductive technologies, access to elective cosmetic or other surgery, pornography, abortion, access to contemporary medical technologies, dress codes related to cultural or religious beliefs, parental rights and the treatment of children, privacy in the digital age.",
      "EN4 — Perspectives are the attitudes, values and/or beliefs of individuals and groups that shape and determine the ethical issue and the nature of the debate."
     ],
     "clarifications": {
      "date": "December 2017",
      "points": [
       "The issue is health-related, controversial, of current public concern, with contrasting perspectives among groups; the clarification assumes a New Zealand issue.",
       "Analysis should be supported by recent, relevant evidence.",
       "Implications for well-being are considered against CURRENT New Zealand practice, usually shaped by law or social norms and often aligned with one perspective.",
       "A critical perspective is needed at all levels: questioning assumptions, identifying who benefits or is disadvantaged, focusing on key aspects, linking to underlying concepts.",
       "Achieved: explain contrasting perspectives and their reasons, with at least two groups for each opposing view; focus on major stakeholder groups rather than individuals' opinions; explain implications of current NZ practice at societal, interpersonal and personal levels, including short- and long-term, positive and negative impacts.",
       "Merit: a balanced account of the differing and opposing perspectives with clear links to underlying concepts.",
       "Excellence: insight into why perspectives differ, including their underpinning ethical principles; focus on the most crucial aspects; coherent, consistent evidence with links to underlying concepts throughout."
      ]
     },
     "nmr": [
      "Issues seen in 2025: assisted euthanasia, child immunisation, abortion, and transgender people in sport. Choose an appropriate issue (EN3).",
      "Include at least two groups for each perspective, ideally major stakeholder groups rather than individuals.",
      "Where international views have shaped the debate, show how they influenced the New Zealand debate; otherwise use groups local to the country being examined, and show where groups are based.",
      "Wellbeing implications must be of CURRENT PRACTICE (e.g. existing law or social norms), not of the issue in the abstract.",
      "For Excellence, clearly link each group's perspective to its ethical foundations.",
      "A critical lens is required at all levels (challenging assumptions, who benefits or is disadvantaged), and analysis at all levels must be supported by recent, relevant evidence."
     ],
