     "title": "Demonstrate understanding of the meaning of a media text through different readings",
     "criteria": {
      "achieved": "Demonstrate understanding of the meaning of a media text through different readings.",
      "merit": "Demonstrate in-depth understanding of the meaning of a media text through different readings.",
      "excellence": "Demonstrate perceptive understanding of the meaning of a media text through different readings."
     },
     "notes": [
      "EN2 — Demonstrate understanding involves explaining the meaning of a media text through different readings.",
      "EN2 — Demonstrate in-depth understanding involves analysing the effect of different readings of a media text. This analysis may involve the ways in which a reading uncovers, adds, or changes the meaning of a media text and may make connections to media theory.",
      "EN2 — Demonstrate perceptive understanding involves evaluating the significance of the effect of different readings for the text and/or society. This significance may include aesthetic, social, cultural, political, historical, economic, technological, or ideological considerations.",
      "EN3 — Different readings involve interpreting the text from different perspectives or theoretical viewpoints in order to understand a possible meaning. These may include: auteur, genre, technical, representational, stylistic, narrative, cultural, gendered, psychological, political, historical, sociological, semiotic, director, dominant, intended, negotiated, variant, opposition."
     ],
     "clarifications": {
      "date": "Updated December 2017",
      "points": [
       "The standard explores a text's meaning through TWO different readings; it is not a discussion of a theory or issue supported by textual evidence (e.g. a genre reading of Double Indemnity should examine how noir conventions shape meaning in that film, not list noir features).",
       "BOTH readings must reach the grade awarded: one Merit reading and one Excellence reading gives Merit overall.",
       "For Merit and Excellence, students analyse and evaluate the effect of their readings on the text and/or society, grounded in the text and supported by textual evidence.",
       "The two readings must be sufficiently distinct: two genre conventions are not two readings; a gendered reading of the femme fatale and a historical reading of feminism are not distinct enough.",
       "Students should not use the same evidence for both readings.",
       "Evidence from beyond the text is allowed (e.g. a director's other films in an auteur reading) but the focus must stay on the one text.",
       "Texts must be age-appropriate; restricted-rating texts (e.g. R18) are not suitable for students under that age."
      ]
     },
