     "notes": [
      "EN2 — Demonstrate understanding involves explaining how and/or why an aspect of New Zealand culture or society is represented.",
      "EN2 — Demonstrate in-depth understanding involves analysing the impact of the media representation in shaping and/or reflecting an aspect of New Zealand culture or society. An impact may be social, cultural, political, historical, economic, technological, or ideological.",
      "EN2 — Demonstrate perceptive understanding involves evaluating the impact of the media representation of an aspect of New Zealand culture or society.",
      "EN3 — Media representations refers to the way a group, issue, idea, event, or place is represented in the media. A representation communicates messages and values that have social significance, reflecting world views, ideologies, societal and cultural assumptions, and biases. It may be broad (e.g. New Zealand as clean and green; New Zealand's drinking culture), a group or place (e.g. tangata Pasifika, Aucklanders, rural New Zealanders), more specific (a teenage subculture) or a specific cultural or social issue (e.g. racial hate crimes)."
     ],
     "clarifications": {
      "date": "Updated December 2017",
      "points": [
       "Students explain how and/or why an aspect of New Zealand society or culture is represented; the focus is evaluating the media context and how and why meaning is created through the representation.",
       "Beyond the media texts that construct the representation, students should find sources that support their reasons for how/why it takes that form. At level 8 a variety of texts is needed (e.g. for drink-driving culture: a driver survey, historical data, or a feature article on economic impact, not just the advertisements).",
       "The discussion centres on the representation, not close readings of individual texts; Merit and Excellence analysis/evaluation addresses the overall representation's impact in shaping or reflecting New Zealand society, not each text separately.",
       "Evidence texts must be relevant to the representation and aspect discussed.",
       "Students should avoid repeating material from NZQA's exemplars (e.g. the 'kiwi male' may still be explored, but with different evidence)."
      ]
     },
