     "criteria": {
      "achieved": "Demonstrate understanding of a significant development in the media.",
      "merit": "Demonstrate in-depth understanding of a significant development in the media.",
      "excellence": "Demonstrate perceptive understanding of a significant development in the media."
     },
     "notes": [
      "EN2 — Demonstrate understanding involves identifying a significant development in the media and explaining how and/or why it has occurred.",
      "EN2 — Demonstrate in-depth understanding involves analysing a significant development in the media by explaining its impact. An impact may be social, cultural, political, historical, economic, technological, or ideological.",
      "EN2 — Demonstrate perceptive understanding involves evaluating the impact of a significant development in the media on society and/or the media.",
      "EN3 — Development in the media means an innovative change or advancement that affects one or more mediums. Examples may include change(s) in ownership, technology, form, content, delivery, reception, legislation or audience."
     ],
     "clarifications": {
      "date": "Updated December 2021",
      "points": [
       "For Achieved, students must go beyond naming and describing the development and explain why and/or how it occurred, using only relevant history — not a full chronology of events or technology.",
       "A hypothesis or research question can help students explore the development's impact. At Excellence, students may evaluate wider impact, including current or future issues, benefits, effects and consequences for media or society.",
       "The development must have wide scope and national, international or global significance — not minor or localised. A single new version of a streaming service may be too narrow.",
       "Students should explain, analyse and evaluate a development rather than only list the pros and cons of a media issue.",
       "Research, viewpoints and case studies should be integrated; a broad range of sources presenting multiple viewpoints supports an in-depth or perceptive account. A bibliography or other referencing may be included.",
       "Students should avoid repeating material from NZQA's online exemplars (e.g. music streaming may still be explored with different evidence or a different line of discussion)."
      ]
     },
