      "EN2 — Critically analyse (Excellence) involves: comprehensively examining the safety management issues for a selected outdoor activity; evaluating the issues in terms of their relative importance; questioning and challenging assumptions and practices relating to safety management in outdoor activities.",
      "EN3 — Safety management issues include those related to: site visits, environmental risks, legislation (e.g. environmental care code), consultation with stakeholders (e.g. land owner, iwi), cultural history, conservation, impact on ecosystems, sustainability, ethics, school policies, people (behaviour, experience, knowledge, attitude), equipment. School safety management tools are available from EONZ.",
      "EN4 — Devise safety management strategies involve considering what plans may need to be put into place to be proactive in ensuring that outdoor activity is managed safely.",
