     "title": "Devise strategies for a physical activity outcome",
     "criteria": {
      "achieved": "Devise strategies for a physical activity outcome.",
      "merit": "Devise in-depth strategies for a physical activity outcome.",
      "excellence": "Devise comprehensive strategies for a physical activity outcome."
     },
     "notes": [
      "EN2 — Devise strategies (Achieved) involves: selecting and explaining the knowledge that underpins the strategies to achieve the physical activity outcome; trialling and making adjustments to the strategies in order to achieve the physical activity outcome.",
      "EN2 — Devise in-depth strategies (Merit) involves selecting and explaining, using coherent reasoning, the knowledge that underpins the strategies to achieve the physical activity outcome.",
      "EN2 — Devise comprehensive strategies (Excellence) involves selecting and explaining, using coherent and insightful reasoning by questioning and challenging assumptions, the knowledge that underpins the strategies to achieve the physical activity outcome.",
      "EN3 — Devise strategies is the process by which knowledge is applied to meet the intended purpose of the physical activity outcome for self or others. This involves developing the strategies, trialling them and adjusting them as a result of a process of ongoing reflection.",
      "EN4 — Knowledge relates to: biophysical (may include anatomy, biomechanics, physiology, psychology, skill acquisition, methods/principles of training); socio-cultural (may include societal, political, economic, environmental, ethical, cultural, historical factors); the specific physical activity context.",
      "EN5 — A physical activity outcome is the goal, purpose, or end point of the activity, such as developing fitness or improving game play.",
      "EN6 — A physical activity outcome may relate to working with individuals or groups in: outdoor education experiences, recreation activities, festival/cultural activities, coaching experiences, physical performance improvement."
     ],
     "clarifications": {
      "date": "December 2018 (updated to address issues arising from moderation)",
      "points": [
       "Students must develop, trial and adjust their strategies with the aim of achieving the outcome. They are NOT required to evaluate the strategies.",
       "Students should identify one specific physical activity outcome, not a range of possible outcomes.",
       "Focus on the strategies most relevant to the outcome; the strategies explained should be the ones trialled.",
       "Responses must include: a clear statement of the intended outcome; clear identification of each strategy; how and why each strategy will be applied to meet the outcome; specific examples of how each would be applied.",
       "Strategies are trialled and adjusted BEFORE the outcome is completed, not evaluated afterwards. Evidence of each strategy being trialled with supporting examples, and an explanation of how and why each needs adjusting in line with the student’s reflection, is required; if no adjustment is needed, say so with an explanation related to the outcome."
      ]
     },
     "nmr": [
      "Good practice (2025 round): a clear, succinct outcome; relevant strategies at level 8; an explanation of how and why each strategy would meet the outcome; strategies trialled with evidence and adjusted with reasons linked to the outcome.",
      "To strengthen: set ONE intended outcome, identified before trialling; knowledge behind each strategy should relate directly to that outcome.",
      "Trialling needs supporting examples, and adjustments should follow from the trials and relate to the outcome.",
      "Many students evaluated only at the end of the event, programme or experience rather than during trialling and adjustment."
     ],
