   "discipline": "Level 3 Physics internals are judged on Level 8 physics understanding and, in the practical, on quantitative reasoning with uncertainties: a theory tested against the student's own data with a graphical analysis whose uncertainty is consistent with the data. Higher grades come from explaining how and why, then linking ideas into a coherent picture or critical discussion specific to the situation. Describing a context or issue well, length and referencing are never the criterion.",
