      "EN3 — Psychological approaches refer to paradigms about people and the way that they function. There may be several different theories within an approach, but they share common assumptions that tie them to that approach. Different approaches may offer different explanations for behaviours. Examples include: behavioural, biological, cognitive, sociocultural, evolutionary, humanistic, psychodynamic."
