      "EN2 — Comprehensively analyse (Excellence) involves a detailed critique focusing on how a key piece of research has had a positive or negative impact on society. The detailed critique includes the significance of methodology, issues and validity of findings.",
      "EN3 — A key piece of research is a study from a recognised academic journal or equivalent publication, or a summary of an academic study, where the design can be determined and analysed. The research has had a demonstrable effect on the development of psychological theory or practice and has had an impact on society. Examples include: the Rosenhan Experiment; the Milgram Experiment; Stanford Prison Experiment; the Dunedin Study; Watson and Rayner."
