     "title": "Conduct independent psychological research with consultation",
     "criteria": {
      "achieved": "Conduct independent psychological research with consultation.",
      "merit": "Conduct, in depth, independent psychological research with consultation.",
      "excellence": "Comprehensively conduct independent psychological research with consultation."
     },
     "notes": [
      "EN2 — Conduct (Achieved) involves: developing a statement of the aim and purpose linked to a psychological concept or idea; selecting an appropriate research method; developing the procedure; considering and complying with the New Zealand Code of Ethics; selecting and recording data; reaching a valid conclusion derived from the findings which is relevant to the purpose of the investigation; interpreting and reporting on the findings.",
      "EN2 — Conduct, in depth (Merit) involves: effective research design; describing the reasons for the choice of the method used to conduct psychological research; evaluating the appropriateness of the method design and/or the validity and reliability of the data; making reference to resources, for example the New Zealand Code of Ethics and statistical analysis; discussing the psychological ideas relating to the research based on the findings.",
      "EN2 — Comprehensively conduct (Excellence) involves: justifying the research design and method used; using the findings to inform future research direction or next steps that might be taken; providing a list of sources.",
      "EN3 — With consultation involves the teacher providing feedback, for example: appropriateness of the psychological research; progress discussions; ensuring the proposed research is ethical; providing broad experimental conditions such as the availability of equipment or participants.",
      "EN4 — Psychological research refers to research carried out in the context of studying human or non-human animal behaviour.",
      "EN5 — Independent involves students designing and conducting their own psychological research."
     ],
     "clarifications": {
      "date": "undated (NZQA Level 3 information page, sighted October 2026)",
      "points": [
       "The standard requires systematic steps; the task can be formatted with headings or prompts for students to follow.",
       "Consultation: students should expect feedback from the teacher about ethical and other appropriate features of their research plan BEFORE collecting the data, and these features must be evident in the responses they produce.",
       "Aim and purpose: the aim must be based on a psychological concept or idea from recognised psychological sources, not only the student's own ideas.",
       "Research design: for Merit, students must explicitly state the reasons for the choice of research method used.",
       "Data and findings: use clearly labelled and defined information or summary data, and support findings with summary evidence or data. An appendix of raw data or other research materials is optional."
      ]
     },
     "nmr": [
      "Strong responses built on a solid foundation of existing published research, which justified the design and method, supported discussion of findings and explained differences. Loose replications allowed comparison with original findings and justification of procedural changes.",
      "Link the research clearly to relevant theory — e.g. a horoscope-accuracy study should connect to the Forer effect. Supplying an extensive list of suitable published studies helps.",
      "Ethics is the most common difficulty: many responses fail the Achieved requirement of considering and complying with the NZ Code of Ethics. Students must explain how their procedure complied; generic DRIPCD points alone do not meet the standard.",
      "The most common breach is Principle 3 (Integrity in Relationships), 3.1.5 avoiding deception. Choose an appropriate context with teacher feedback; social-influence research usually requires deception and is generally best avoided. An in-class 'ethics committee' is highly effective. Cost-benefit justification of breaches is not recommended (it reflects professional judgement, not compliance).",
      "Excellence 'research design' means how participants are allocated to conditions (independent groups, repeated measures, matched participants); students should justify the choice over alternatives — strengths, weaknesses, fit with the aim.",
      "No method is prescribed, but it must suit the aim and affects validity (e.g. a single-subject design requires discussion of generalisability).",
      "No specific statistical test is required; qualitative methods are acceptable and statistics are not required where unsuitable (e.g. case studies). Quantitative data need descriptive statistics (mean, median, mode) with discussion of the most appropriate; simple tests (t-test, chi-squared) are typical; hand calculation is not required but students must explain what results mean. Depth of analysis should match the claims in the conclusion."
     ],
